import heapq

class TaskQueue:
    def __init__(self):
        self._queue = []
        self._counter = 0

    def add_task(self, task_fn, priority=0):
        heapq.heappush(self._queue, (-priority, self._counter, task_fn))
        self._counter += 1

    def process(self):
        results = []
        while self._queue:
            _, _, task_fn = heapq.heappop(self._queue)
            results.append(task_fn())
        return results

    @property
    def size(self):
        return len(self._queue)

