class TaskQueue {
  constructor() {
    this._queue = [];
    this._counter = 0;
  }

  addTask(taskFn, priority = 0) {
    this._queue.push({ taskFn, priority, order: this._counter++ });
  }

  process() {
    this._queue.sort((a, b) => {
      if (b.priority !== a.priority) return b.priority - a.priority;
      return a.order - b.order;
    });
    const results = this._queue.map(item => item.taskFn());
    this._queue = [];
    return results;
  }

  get size() {
    return this._queue.length;
  }
}
